        return inputs.get(pointer++);
    }

    static long solve() {
        long[] nm = rns();
        long n = nm[0], m = nm[1];
        long pre = 1;
        long M = mod(m);
        long res = 0;
        long ans = M;
        long ans1 = M;
        int[] p = getPrimes((int) n + 10);
        for (int i = 2; i <= n; i++) {
            if (pre <= m && p[i] != 0) pre = pre * i;
            if (pre > m) {
                ans = 0;
            } else {
                ans = mul(ans, (long) Math.floor((double) m / pre));
            }
            ans1 = mul(ans1, M);
            res = mod(res + ans1 - ans);
        }
        return res;
    }

    static int[] getPrimes(int n) {
        int[] nums = new int[n + 1];
        Arrays.fill(nums, 1);
        nums[0] = 0;
        if (n >= 1) nums[1] = 0;
        List<Integer> primes = new ArrayList<>();
        for (int i = 2; i <= n; i++) {
            if (nums[i] != 0) primes.add(i);
            for (int j = 0; j < primes.size() && primes.get(j) <= (double) n / i; j++) {
                nums[primes.get(j) * i] = 0;
                if (i % primes.get(j) == 0) break;
            }
        }
        return nums;
    }

    static long mod(long num) {
        if (num >= MOD) return num % MOD;
        else if (num < 0) return (num % MOD + MOD) % MOD;
        return num;
    }

    static long mul(long... args) {
        if (args.length == 0) throw new RuntimeException("参数不能为空");
        if (args.length == 1) return args[0];
        long a = args[0], b = args[1];
        if (args.length > 2) {
            long[] rest = new long[args.length - 1];
            rest[0] = mul(a, b);
            System.arraycopy(args, 2, rest, 1, args.length - 2);
            return mul(rest);
        }
        return ((long) Math.floor((double) a / 65536) * b % MOD * 65536 + (a & 65535) * b) % MOD;
    }

    static long rn() {
        return Long.parseLong(read().trim());
    }

    static long[] rns() {
        String[] parts = read().trim().split("\\s+");
        long[] res = new long[parts.length];
        for (int i = 0; i < parts.length; i++) res[i] = Long.parseLong(parts[i]);
        return res;
    }

    static long[] re() {
        String[] parts = read().trim().split("\\s+");
        long[] res = new long[parts.length];
        for (int i = 0; i < parts.length; i++) res[i] = Long.parseLong(parts[i]) - 1;
        return res;
    }

    static String mainRun() {
